class Solution {
  public int[] twoSum(int[] numbers, int target) {
    int left = 0, right = numbers.length - 1;
    while (left < right) {
      int sum = numbers[left] + numbers[right];
      if (sum == target) return new int[] {left + 1, right + 1};
      if (sum < target) left++;
      else right--;
    }
    return new int[] {-1, -1};
  }
}

class Solution {
  public boolean isPalindrome(String s) {
    int left = 0, right = s.length() - 1;
    while (left < right) {
      while (left < right && !Character.isLetterOrDigit(s.charAt(left))) left++;
      while (left < right && !Character.isLetterOrDigit(s.charAt(right))) right--;
      if (Character.toLowerCase(s.charAt(left)) != Character.toLowerCase(s.charAt(right))) return false;
      left++;
      right--;
    }
    return true;
  }

  public boolean isPalindromeRecursive(String s) {
    return check(s, 0, s.length() - 1);
  }

  private boolean check(String s, int left, int right) {
    if (left >= right) return true;
    if (!Character.isLetterOrDigit(s.charAt(left))) return check(s, left + 1, right);
    if (!Character.isLetterOrDigit(s.charAt(right))) return check(s, left, right - 1);
    return Character.toLowerCase(s.charAt(left)) == Character.toLowerCase(s.charAt(right))
        && check(s, left + 1, right - 1);
  }
}

class Solution {
  public int removeDuplicates(int[] nums) {
    if (nums.length == 0) return 0;
    int write = 1;
    for (int read = 1; read < nums.length; read++) {
      if (nums[read] != nums[write - 1]) nums[write++] = nums[read];
    }
    return write;
  }
}

class Solution {
  public int removeElement(int[] nums, int val) {
    int write = 0;
    for (int read = 0; read < nums.length; read++) {
      if (nums[read] != val) nums[write++] = nums[read];
    }
    return write;
  }
}

class Solution {
  public void moveZeroes(int[] nums) {
    int write = 0;
    for (int read = 0; read < nums.length; read++) {
      if (nums[read] != 0) nums[write++] = nums[read];
    }
    while (write < nums.length) nums[write++] = 0;
  }
}

class Solution {
  public int[] sortedSquares(int[] nums) {
    int n = nums.length, left = 0, right = n - 1, write = n - 1;
    int[] ans = new int[n];
    while (left <= right) {
      int a = nums[left] * nums[left];
      int b = nums[right] * nums[right];
      if (a > b) {
        ans[write--] = a;
        left++;
      } else {
        ans[write--] = b;
        right--;
      }
    }
    return ans;
  }
}

class Solution {
  public void reverseString(char[] s) {
    int left = 0, right = s.length - 1;
    while (left < right) {
      char temp = s[left];
      s[left++] = s[right];
      s[right--] = temp;
    }
  }

  public void reverseStringRecursive(char[] s) {
    reverse(s, 0, s.length - 1);
  }

  private void reverse(char[] s, int left, int right) {
    if (left >= right) return;
    char temp = s[left];
    s[left] = s[right];
    s[right] = temp;
    reverse(s, left + 1, right - 1);
  }
}

class Solution {
  public void merge(int[] nums1, int m, int[] nums2, int n) {
    int i = m - 1, j = n - 1, write = m + n - 1;
    while (j >= 0) {
      if (i >= 0 && nums1[i] > nums2[j]) nums1[write--] = nums1[i--];
      else nums1[write--] = nums2[j--];
    }
  }
}

class Solution {
  public boolean hasCycle(ListNode head) {
    ListNode slow = head, fast = head;
    while (fast != null && fast.next != null) {
      slow = slow.next;
      fast = fast.next.next;
      if (slow == fast) return true;
    }
    return false;
  }
}

class Solution {
  public ListNode middleNode(ListNode head) {
    ListNode slow = head, fast = head;
    while (fast != null && fast.next != null) {
      slow = slow.next;
      fast = fast.next.next;
    }
    return slow;
  }
}

class Solution {
  public int maxArea(int[] height) {
    int left = 0, right = height.length - 1, best = 0;
    while (left < right) {
      int area = Math.min(height[left], height[right]) * (right - left);
      best = Math.max(best, area);
      if (height[left] < height[right]) left++;
      else right--;
    }
    return best;
  }
}

